using System;
using System.IO;
using System.Text.Json;
using GameClient;
using Xunit;

namespace GameClientTests
{
    // fixtures.json is generated by `node js/make-fixtures.mjs` from the real boombrawl
    // shared/movement.mjs on a real captured arena (js/arena.txt). Each row is
    // [x, y, dirX, dirY, speed, expectedX, expectedY].
    public class MovementPortTests
    {
        static readonly JsonElement F =
            JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "fixtures.json"))).RootElement;

        static readonly string Grid = F.GetProperty("grid").GetString();
        static readonly int W = F.GetProperty("width").GetInt32();
        static readonly int H = F.GetProperty("height").GetInt32();

        static bool Blocked(int cx, int cy) =>
            cx < 0 || cy < 0 || cx >= W || cy >= H || Grid[cy * W + cx] != '.';

        static void CheckRows(string set)
        {
            int n = 0;
            foreach (JsonElement row in F.GetProperty(set).EnumerateArray())
            {
                int x = row[0].GetInt32(), y = row[1].GetInt32(), dx = row[2].GetInt32(), dy = row[3].GetInt32();
                int speed = row[4].GetInt32(), ex = row[5].GetInt32(), ey = row[6].GetInt32();
                (int ax, int ay) = Movement.StepEntity(x, y, dx, dy, speed, Blocked);
                Assert.True(ax == ex && ay == ey,
                    $"{set}[{n}]: StepEntity({x}, {y}, {dx}, {dy}, {speed}) = ({ax}, {ay}), JS gives ({ex}, {ey})");
                n++;
            }
            Assert.True(n > 0, $"no rows in {set}");
        }

        [Fact]
        public void WorldToCell_FloorsLikeMathFloor()
        {
            foreach (JsonElement c in F.GetProperty("worldToCell").EnumerateArray())
                Assert.Equal(c[1].GetInt32(), Movement.WorldToCell(c[0].GetInt32()));
        }

        [Fact]
        public void WallApproaches_AcrossTheCornerAssistThreshold_MatchJavaScript()
        {
            // Lane offsets -70..70 including exactly +-63, +-64, +-65 against every wall on the arena.
            CheckRows("thresholds");
        }

        [Fact]
        public void RandomWalksOnTheRealArena_MatchJavaScript()
        {
            CheckRows("walks");
        }

        [Fact]
        public void BothDirectionsGiven_XWins()
        {
            CheckRows("diagonal");
        }

        [Fact]
        public void NoDirection_DoesNotMove()
        {
            Assert.Equal((384, 640), Movement.StepEntity(384, 640, 0, 0, 96, Blocked));
        }
    }
}
